CUCLACommManager::CUCLACommManager(USBD_NODE_ID usbNodeId, SUsbDescriptors * descs) :

    IPeripheralUpdater(usbNodeId, usbDeviceType),
    CUsbCommBase( descs, usbNodeId )
{

    Debug::trace("CUCLACommManager", "CUCLACommManager constructor");

    lastSRecord_ = false;

    attemptToSendUpdateCntr_ = 0;
    retryCount = 4;

    codeUpdaterStateMachine_ = WAITING_TO_SEND_UPDATE;

    sizeModeSRecord_ = false;

    resetTransferCounters();

    pIntData_ = NULL;
    intDataLength_ = 0;

    xmitting_ = false;

    flashImgBuffer_ = 0;

    registerEvent(VersionManagerDev, 18);
    //create and start our thread!!
    pCUCLACommManagerThread = new Util::CTLSThread( *this, THREAD_PRIORITY_NORMAL, 0, "CUCLACommManager Thread", false, false, false );
    if (pCUCLACommManagerThread)
        pCUCLACommManagerThread->RestartThread();

}


