DWORD CUCLACommManager::Run()
{
    try
    {
        registerEvent(VersionManagerDev, 18);   //CancelUpgrade

        while (!m_ExitEvent.IsEventSet())
        {

            {//here so that the run thread will release the critical section.

                Util::CLockCriticalSection lock( CUCLACommManagerCS );

                switch (codeUpdaterStateMachine_)
                {
                    case WAITING_TO_SEND_UPDATE:
                        {
                            attemptToSendUpdateCntr_ = 0;
							Debug::trace("CUCLACommManager.SendingUpdate", HobString("SM:WAITING_TO_SEND_UPDATE:waiting send out update message"));
                        }
                        break;
                    case SENDING_UPDATE:
                        {
                            if ((intDataLength_ > 0) && (!xmitting_))
                            {
                                Debug::trace("CUCLACommManager.SendingUpdate", HobString("SM:SENDING_UPDATE:send out update message"));

                                codeUpdaterStateMachine_ = WAITING_FOR_STATUS_START;
                                sendRecord();
                            }
                            else
                            {
                                attemptToSendUpdateCntr_++;
                                Debug::trace("CUCLACommManager.SendingUpdate", HobString("SM:SENDING_UPDATE:cannot send update message"));

                                if (attemptToSendUpdateCntr_ > 100)
                                {
                                    Debug::trace("CUCLACommManager", HobString("SM:SENDING_UPDATE:filure count exceeded. cancel sending update message"));
                                    codeUpdaterStateMachine_ = WAITING_TO_SEND_UPDATE;
                                }
                            }

                        }
                        break;
                    case WAITING_FOR_STATUS_START:
                        {
                            /*processingList will be empty until we receive the ready message from the CLA.*/
							Debug::trace("CUCLACommManager.SendingUpdate", HobString("SM:WAITING_FOR_STATUS_START:waiting for message"));
                        }
                        break;
                    case DOWNLOADING_CODE:
                        {
                            //if we still have more s records to send. and we are not currently sending one.
                            //then send the next s record.
                            //this is two steps. first the header then the s record data.
							Debug::trace("CUCLACommManager.SendingUpdate", HobString("SM:DOWNLOADING_CODE:downloading"));
                            if ((intDataLength_ > 0) && (!xmitting_))
                                sendRecord();
                        }
                        break;
                    case LAST_SRECORD_SENT:
                        {
                            //wait for response from CLA
							Debug::trace("CUCLACommManager.SendingUpdate", HobString("SM:LAST_SRECORD_SENT:waiting for response from CLA"));
                        }
                        break;
                    case PAUSE_BEFORE_RETRY:
                        {
                            PAL_absclass::PAL_sleep(30000);
                            Debug::trace("CUCLACommManager", HobString("SM:PAUSE_BEFORE_RETRY:pause complete"));
                            codeUpdaterStateMachine_ = WAITING_FOR_STATUS_START;
                        }
                        break;
                    case DOWNLOAD_COMPLETE:
                        {
                            //if there is nothing currently being processed and there is
                            //nothing remaining to be processed then this flash is complete.
							Debug::trace("CUCLACommManager.SendingUpdate", HobString("SM:DOWNLOADING_COMPLETE:downloading complete"));
                        }
                        break;
                    case ALL_DOWNLOADS_COMPLETE:
                        {
                            Debug::trace("CUCLACommManager", HobString("SM:ALL_DOWNLOADS_COMPLETE:all node flashs complete. wait to send next update message if necessary. transition to WAITING_TO_SEND_UPDATE"));
                            UpgradePeripheral msg(UpgradeComplete, LabelApplier, CompactLabelApplier_EPSAC2);
                            dispatchEvent(&msg, this);
                            codeUpdaterStateMachine_ = WAITING_TO_SEND_UPDATE;
                        }
                        break;
                    default:
                        break;
                }
            }
            PAL_absclass::PAL_waitForSingleObj(m_ExitEvent, 10000);    //reduce sleep time when finished debugging!
        }
    }
    catch (...)
    {
        LogCatch;
    }
    return 0;
}

