HobVersion::VersionType CUCLACommManager::getSoftwareType(UINT16 nodeID, LaSoftwareComponent type)
{

    switch (nodeID)
    {
        case 2://CLA
            {
                switch (type)
                {
                    case claData:
                        return HobVersion::CLADataSW;
                        break;
                    case claBoot:
                        return HobVersion::CLABootSW;
                        break;
                    case claApp:
                        return HobVersion::CLAAppSW;
                        break;
                    default:
                        return HobVersion::CLAAppSW;
                        break;
                }
            }
            break;
        default:
            break;
    }

    return HobVersion::UnknownComponent;
}

void CUCLACommManager::processUsbMessage( std::string & msg, CUsbPipe::EvolPipeType UNUSED(pipe_type) )
{
    UNREFERENCED_PARAMETER(pipe_type);
    const char * ptr = msg.c_str();

    USBEvolHeader usbEvolHeader(ptr, false);

    UINT16 physicalAddress = usbEvolHeader.getSourcePhysicalAddress();
    UINT16 logicalAddress = usbEvolHeader.getSourceLogicalAddress();

    ptr+= 10;

    if (logicalAddress == USBEvolHeader::CLA)
    {
        receivedCLADevMessage((CompactLaGeneric *) ptr, physicalAddress);
    }
    else
    {
        Debug::trace("CUCLACommManager.Error", HobString("Unknown Message logicalAddress:: 0x") +
                HobString(Hex::toString(usbEvolHeader.getSourceUniqueAddress())));
        usbEvolHeader.show();
    }
    //this might also be needed for Windows
    #if defined ( __linux__ )
    //we have consumed the message, allow the IN pipe to continue reading.
    //signalPipe();
	#endif
}

void CUCLACommManager::receivedCLADevMessage(CompactLaGeneric *UNUSED(genMsg), UINT16 UNUSED(physicalAddress))
{
    UNREFERENCED_PARAMETER(physicalAddress);
    UNREFERENCED_PARAMETER(genMsg);
}

static const unsigned long maxIntXferSize = 64;

void CUCLACommManager::sendRecord()
{
    UINT32 size = 0;
    char str[255];
    DWORD result = OK;
    bool is_custom_code = false;

    xmitting_ = true;
    lastSRecord_ = false;

    //this is for transmitting firmware in s record format.
    //each packet will contain exactly one s record.
    //thus s records cannot be larger than 64 bytes.
    //the size of the packet is the size of the current s record.
    //the size of the s record is in the s record data.
    if (sizeModeSRecord_)
    {

        if (pIntData_[0] != 'S')
        {
            Debug::trace("CUCLACommManager.Error", "***In Srecord Mode but not Srecord***");
            pIntData_ = 0;
            intDataLength_ = 0;

            xmitting_ = false;
            return;
        }

        sscanf((const char *)(pIntData_ + 2), "%02X", &size);
        size *= 2;
        size += 6;
        //clip the s record to 64 bytes.
        if (size > maxIntXferSize)
            size = maxIntXferSize;

        if ((pIntData_[0] == 'S') && (pIntData_[1] == '7'))
        {

            Debug::trace("CUCLACommManager.LastSRecord", "***S7 found***");
            codeUpdaterStateMachine_ = LAST_SRECORD_SENT;
            lastSRecord_ = true;
        }

    }
    else
    {
        size = maxIntXferSize;
        if (size > intDataLength_)
            size = intDataLength_;
    }

    usbEvolHdr_.setMessageLength((UINT16)size);
    usbEvolHdr_.Serialize( str );

    memcpy( &str[10], (char *) &pIntData_[0], size);
    sendUsbInterruptMessage( ( const char * ) str,  size + 10, result, is_custom_code );

    intDataLength_ = 0;
    xmitting_ = false;
    pIntData_ = NULL;
}

